void CoverEnumCoordinate(FAutomationTestBase& Test)
{
	UEnum* const Enum = StaticEnum<EMjCoordinate>();
	Test.TestNotNull(TEXT("EMjCoordinate is registered"), Enum);
	if (Enum == nullptr)
	{
		return;
	}
	Test.TestEqual(TEXT("EMjCoordinate keyword count"),
		Enum->NumEnums() - 1, 2);
	Test.TestEqual(TEXT("EMjCoordinate[0] keyword"),
		Enum->GetDisplayNameTextByIndex(0).ToString(),
		FString(TEXT("local")));
	Test.TestEqual(TEXT("EMjCoordinate[1] keyword"),
		Enum->GetDisplayNameTextByIndex(1).ToString(),
		FString(TEXT("global")));
}

